        if (terminal) return
        terminal = true
        val active = controller
        if (active != null) {
            active.animateToStart { restoreCurrentState() }
        } else {
            restoreCurrentState()
            settle()
        }
    }

    fun commit() {
        if (terminal) return
        terminal = true
        commitPreviousState()
        val active = controller
        if (active != null) active.animateToEnd() else settle()
    }

    private fun settle() {
        if (settled) return
        settled = true
