final class BackgroundShaderResources {
  ui.FragmentProgram? _program;
  ui.FragmentShader? _shader;
  Future<void>? _loading;
  bool _disposed = false;

  Future<void> load() {
    if (_disposed) {
      return Future<void>.error(StateError('Resources already disposed'));
    }
    return _loading ??= _load().whenComplete(() { _loading = null; });
  }

  Future<void> _load() async {
    if (_program != null) {
      return;
    }
    final program =
        await ui.FragmentProgram.fromAsset('shaders/background.frag');
    if (_disposed) {
      throw StateError('Disposed while loading background shader');
    }
    final shader = program.fragmentShader();
    _program = program;
    _shader = shader;
  }

  ui.FragmentShader get shader {
    final value = _shader;
    if (value == null) {
      throw StateError('Background shader has not been loaded');
    }
    return value;
  }

  void dispose() {
    if (_disposed) return;
    _disposed = true;
    _shader?.dispose();
    _shader = null;
    _program = null;
  }
